insert into passages (id, text, difficulty_level, b, active) values
('5c1dde7b-501c-4a9b-9607-e947b9768d08', 'Sleep researchers have long been interested in why humans spend roughly a third of their lives unconscious, and recent studies have begun to clarify some of the biological functions that sleep serves. One important discovery involves the brain''s glymphatic system, a network that becomes significantly more active during sleep and helps clear away metabolic waste products, including proteins associated with neurodegenerative diseases, that accumulate in the brain during waking hours. Sleep also plays a critical role in memory consolidation, the process by which short-term memories formed during the day are strengthened and transferred into long-term storage. Students who sleep well after studying, for example, tend to retain information better than those who stay up late cramming. In addition to these cognitive benefits, adequate sleep supports the immune system, helping the body produce the proteins needed to fight off infection. Despite this growing body of evidence, many people continue to view sleep as a luxury that can be sacrificed in favor of work or other obligations, a habit that sleep researchers warn carries significant long-term health risks.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('06d2f692-7fb7-4279-a90c-a7f164b90a60', 'sentence_completion', 'By next month, she ___ at this company for five years.', NULL, '[{"id": "a", "text": "will have worked"}, {"id": "d", "text": "worked"}, {"id": "b", "text": "will work"}, {"id": "c", "text": "works"}]'::jsonb, 0, '{"strategy": "By next month...for five years = עד החודש הבא...במשך חמש שנים. פעולה שתושלם עד נקודה בעתיד = future perfect.", "correct_reason": "will have worked = תעבוד. future perfect: will have + participle.", "options_analysis": ["נכון! will have worked = future perfect, מציין השלמה עד נקודה בעתיד", "worked = עבר — לא מתאים לפעולה שתימשך עד העתיד", "will work = עתיד פשוט — לא מדגיש השלמה עד נקודת זמן עתידית", "works = הווה — לא מתאים ל''by next month''"]}', 0.82, -1.0, 0.25, 2, 'ai', NULL, true),
('6bd48a27-77e6-4b93-b118-380ab490c6e6', 'sentence_completion', 'The students, most of ___ had studied hard, passed the exam easily.', NULL, '[{"id": "c", "text": "who"}, {"id": "a", "text": "whom"}, {"id": "d", "text": "they"}, {"id": "b", "text": "them"}]'::jsonb, 1, '{"strategy": "most of + פסוקית זיקה = דורש כינוי אובייקט אחרי preposition. most of whom.", "correct_reason": "whom = מהם. אחרי preposition (of) בפסוקית זיקה משתמשים ב-whom.", "options_analysis": ["who = כינוי זיקה לנושא — לא מתאים אחרי preposition", "נכון! whom = כינוי זיקה לאחר preposition (of whom)", "they = כינוי גוף — לא מתאים אחרי preposition בפסוקית זיקה", "them = כינוי אובייקט רגיל — לא מתאים לפסוקית זיקה"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('e6d4365c-3f45-40e8-a47d-a5cca478aef3', 'sentence_completion', 'It is essential that every employee ___ the safety guidelines before starting work.', NULL, '[{"id": "c", "text": "followed"}, {"id": "d", "text": "following"}, {"id": "b", "text": "follow"}, {"id": "a", "text": "follows"}]'::jsonb, 2, '{"strategy": "It is essential that = חיוני ש-. אחרי ביטויי חיוניות בא subjunctive (צורת בסיס).", "correct_reason": "follow = לעקוב. essential that + subject + base form (subjunctive).", "options_analysis": ["עבר לא מתאים לתבנית subjunctive", "ing לא מתאים אחרי that + subject", "נכון! subjunctive: essential that + subject + base form", "follows = מקבל s — לא מתאים ל-subjunctive"]}', 1.08, -1.0, 0.25, 2, 'ai', NULL, true),
('0806b37a-4d61-43e1-bcb1-03f8d72fcf7b', 'sentence_completion', 'No sooner ___ the announcement been made than the stock price began to fall.', NULL, '[{"id": "a", "text": "has"}, {"id": "d", "text": "did"}, {"id": "b", "text": "was"}, {"id": "c", "text": "had"}]'::jsonb, 3, '{"strategy": "No sooner...than = לא מוקדם יותר...מאשר. תבנית ''no sooner had + participle + than'' לרצף מהיר.", "correct_reason": "had = כבר. No sooner had + participle + than = תבנית תקנית.", "options_analysis": ["has לא מתאים לעבר — ''began'' מרמז עבר", "did לא מתאים לתבנית No sooner...than", "was לא מתאים ל-been made שדורש had", "נכון! No sooner had + participle + than = תבנית תקנית לרצף מהיר"]}', 0.97, -1.0, 0.25, 2, 'ai', NULL, true),
('4dca6aeb-2dd7-4b73-b246-e747ada658f4', 'sentence_completion', 'The manager insisted that the report ___ submitted by Friday.', NULL, '[{"id": "a", "text": "be"}, {"id": "d", "text": "is"}, {"id": "c", "text": "was"}, {"id": "b", "text": "being"}]'::jsonb, 0, '{"strategy": "insisted that = התעקש ש-. אחרי insist בא subjunctive (צורת בסיס).", "correct_reason": "be = יהיה. insist that + subject + be (subjunctive).", "options_analysis": ["נכון! subjunctive: insist that + subject + base form (be)", "is = הווה רגיל — לא מתאים ל-subjunctive אחרי insist", "עבר לא מתאים לתבנית subjunctive", "ing לא מתאים אחרי insist that"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('b0bb5b05-f73b-4b04-b8d4-e0f3ce2ecf10', 'sentence_completion', 'Were I ___ you, I would accept the job offer immediately.', NULL, '[{"id": "c", "text": "been"}, {"id": "d", "text": "to be"}, {"id": "b", "text": "being"}, {"id": "a", "text": "be"}]'::jsonb, 1, '{"strategy": "Were I...= תבנית תנאי היפותטי הפוכה (inversion) של ''If I were you''.", "correct_reason": "to be = להיות. ''Were I to be you'' משמש כתבנית פורמלית חלופית ל-if I were you (עם היפוך).", "options_analysis": ["been = participle לא מתאים כאן", "נכון! Were I to be = תבנית פורמלית של תנאי היפותטי בהיפוך", "being = ing לא מתאים אחרי Were I", "be = צורת בסיס לבד לא תקינה בתבנית זו"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
('b0364a1f-cbf0-4ab3-a53b-7c40a990fda5', 'sentence_completion', 'The bridge, construction of ___ began in 2015, was finally completed last year.', NULL, '[{"id": "c", "text": "it"}, {"id": "d", "text": "that"}, {"id": "b", "text": "which"}, {"id": "a", "text": "what"}]'::jsonb, 2, '{"strategy": "construction of...began = בנייתו...החלה. פסוקית זיקה על עצם (bridge), נדרש which אחרי preposition.", "correct_reason": "which = ש-. construction of which = תבנית זיקה תקנית לעצם.", "options_analysis": ["it לא כינוי זיקה תקני כאן", "that לא משמש אחרי preposition כמו of", "נכון! which מתאים לעצם אחרי preposition (of which)", "what לא כינוי זיקה תקני בהקשר זה"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('2dfed44c-19b8-4e60-b3a3-b0aa446b38e2', 'sentence_completion', 'Rarely ___ such a talented young musician performed on this stage.', NULL, '[{"id": "b", "text": "have"}, {"id": "c", "text": "does"}, {"id": "a", "text": "did"}, {"id": "d", "text": "has"}]'::jsonb, 3, '{"strategy": "Rarely...= לעיתים נדירות. תבנית היפוך אחרי מילת שלילה/תדירות נמוכה בתחילת משפט.", "correct_reason": "has = כבר. Rarely has + subject + participle = תבנית היפוך תקנית עם present perfect.", "options_analysis": ["have = רבים — לא מתאים למוסיקאי יחיד", "does לא מתאים לתבנית עם participle", "did לא מתאים לתבנית עם ''performed'' כ-participle", "נכון! Rarely has + subject + participle = תבנית היפוך עם present perfect"]}', 0.77, -1.0, 0.25, 2, 'ai', NULL, true),
('2b43ae86-3e61-41df-b451-b044ed0baa56', 'sentence_completion', 'The evidence presented was insufficient to justify ___ the defendant.', NULL, '[{"id": "c", "text": "convicting"}, {"id": "d", "text": "convicted"}, {"id": "a", "text": "convict"}, {"id": "b", "text": "to convict"}]'::jsonb, 0, '{"strategy": "insufficient to justify = לא מספיק כדי להצדיק. justify נדרש gerund (ing) כמושא.", "correct_reason": "convicting = להרשיע. justify + gerund הוא תבנית תקנית.", "options_analysis": ["נכון! justify + gerund (ing) = תבנית תקנית", "convicted = עבר — לא תקין כמושא ל-justify", "convict לבד ללא ing לא תקין אחרי justify", "to convict = infinitive — justify לא לוקח infinitive"]}', 0.85, -1.0, 0.25, 2, 'ai', NULL, true),
('5bc1c5d0-d91a-4b1f-8fb4-4b2a854675bc', 'sentence_completion', 'He is the only student in the class ___ has completed all the assignments.', NULL, '[{"id": "d", "text": "whose"}, {"id": "c", "text": "who"}, {"id": "b", "text": "which"}, {"id": "a", "text": "whom"}]'::jsonb, 1, '{"strategy": "the only student...has completed = התלמיד היחיד...השלים. פסוקית זיקה על אדם (student) כנושא.", "correct_reason": "who = ש-. who משמש לתיאור אדם כנושא הפסוקית.", "options_analysis": ["whose מציין שייכות, לא מתאים כאן", "נכון! who = מתאים לאדם כנושא הפסוקית", "which משמש לעצמים, לא לאנשים כמו student", "whom משמש למושא, לא לנושא הפסוקית"]}', 1.08, -1.0, 0.25, 2, 'ai', NULL, true),
('5e597a93-e40c-420d-b28c-94a1e8359390', 'sentence_completion', 'Not until she arrived home ___ that she had left her phone at the office.', NULL, '[{"id": "a", "text": "realized she"}, {"id": "b", "text": "she did realize"}, {"id": "c", "text": "did she realize"}, {"id": "d", "text": "she realized"}]'::jsonb, 2, '{"strategy": "Not until = לא עד ש-. תבנית שלילית בתחילת משפט דורשת היפוך.", "correct_reason": "did she realize = הבינה. Not until + clause + did + subject + verb = היפוך תקני.", "options_analysis": ["סדר מילים שגוי לגמרי", "סדר מילים שגוי — auxiliary כפול", "נכון! Not until...did she realize = היפוך תקני", "חסר היפוך אחרי Not until בתחילת המשפט"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('4552cc7b-cbd9-462c-a7af-c0c04856933a', 'sentence_completion', 'The professor, along with his students, ___ conducting research on climate change.', NULL, '[{"id": "d", "text": "have been"}, {"id": "a", "text": "were"}, {"id": "b", "text": "are"}, {"id": "c", "text": "is"}]'::jsonb, 3, '{"strategy": "along with = יחד עם. ''along with'' לא הופך את הנושא לרבים — הנושא הדקדוקי הוא the professor ביחיד.", "correct_reason": "is = הוא. הנושא היחיד (professor) קובע את הפועל, לא ''along with his students''.", "options_analysis": ["have been = רבים — לא מתאים לנושא היחיד", "were = עבר רבים — לא מתאים לא לזמן ולא למספר", "are = רבים — לא מתאים כי ''along with'' לא הופך ל-professor לרבים", "נכון! is = יחיד, מתאים ל''the professor'' כנושא דקדוקי"]}', 1.0, -1.0, 0.25, 2, 'ai', NULL, true),
('fa50bb16-715f-4d29-9440-f87007e5ae27', 'restatement', 'The film, despite receiving mixed reviews, performed well at the box office.', NULL, '[{"id": "a", "text": "Even though the reviews were mixed, the film did well financially."}, {"id": "c", "text": "The film received universally positive reviews."}, {"id": "b", "text": "The film was never released in theaters."}, {"id": "d", "text": "The film performed poorly at the box office because of mixed reviews."}]'::jsonb, 0, '{"strategy": "despite mixed reviews, performed well = למרות ביקורות מעורבות, הצליח. ניגוד.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: ביקורות מעורבות, אך הצליח כלכלית", "הפוך — ''universally positive'' סותר ''mixed reviews''", "סותר את קיום ההצגה בקולנוע", "הפוך — סותר ''performed well at the box office''"]}', 0.78, -1.0, 0.25, 2, 'ai', NULL, true),
('0306ecc4-5213-41db-b4d4-87e8c034dde9', 'restatement', 'The city''s new policy, once implemented, is expected to reduce traffic accidents significantly.', NULL, '[{"id": "b", "text": "The policy is expected to have no effect on traffic accidents."}, {"id": "d", "text": "Once put into effect, the policy should notably decrease traffic accidents."}, {"id": "c", "text": "The city decided not to implement the new policy."}, {"id": "a", "text": "The policy has already failed to reduce accidents."}]'::jsonb, 1, '{"strategy": "once implemented, expected to reduce = לאחר יישום, צפוי להפחית.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''expected to reduce traffic accidents significantly''", "נכון! אותה משמעות בדיוק: לאחר יישום, צפוי להפחית תאונות משמעותית", "סותר ''once implemented'' — יש כוונה ליישם", "סותר ''once implemented'' שמרמז שהמדיניות טרם יושמה או שהצלחתה עדיין לא נבדקה"]}', 0.83, -1.0, 0.25, 2, 'ai', NULL, true),
('8be1a975-814f-4ec9-a347-7fdf0ba26b25', 'restatement', 'Although the ingredients were simple, the chef transformed them into an extraordinary dish.', NULL, '[{"id": "d", "text": "The chef used complicated ingredients to make the dish."}, {"id": "b", "text": "The dish turned out to be ordinary and unremarkable."}, {"id": "c", "text": "Despite using basic ingredients, the chef created an amazing dish."}, {"id": "a", "text": "The chef refused to cook with simple ingredients."}]'::jsonb, 2, '{"strategy": "Although simple...extraordinary = למרות פשטות...יוצא דופן. ניגוד.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''the ingredients were simple''", "הפוך — ''ordinary'' סותר ''extraordinary''", "נכון! אותה משמעות בדיוק: מרכיבים בסיסיים, אך מנה מדהימה", "סותר את קיום המנה שהוכנה"]}', 0.85, -1.0, 0.25, 2, 'ai', NULL, true),
('d9532639-5af1-43b5-ae4d-04647a93790d', 'restatement', 'The committee will not approve the budget unless significant changes are made.', NULL, '[{"id": "b", "text": "The committee has already approved the budget."}, {"id": "a", "text": "The committee will approve the budget without any changes."}, {"id": "c", "text": "No changes are needed for budget approval."}, {"id": "d", "text": "The committee will approve the budget only if major changes are made."}]'::jsonb, 3, '{"strategy": "will not...unless = לא...אלא אם. Unless X, not Y = If not X, not Y.", "correct_reason": "אותה משמעות בדיוק: תאשר רק אם ישונה משמעותית.", "options_analysis": ["סותר את המשפט כולו שמרמז שהתקציב טרם אושר", "הפוך — סותר ''unless significant changes are made''", "הפוך — סותר ''unless significant changes are made''", "נכון! אותה משמעות בדיוק: Unless = רק אם"]}', 0.96, -1.0, 0.25, 2, 'ai', NULL, true),
('1efd874c-f659-465a-b7e2-bce3798d96f3', 'restatement', 'The report, compiled over several months, provides a comprehensive overview of the industry''s challenges.', NULL, '[{"id": "b", "text": "Having been put together over many months, the report offers a thorough look at the industry''s problems."}, {"id": "d", "text": "The report was never actually completed."}, {"id": "c", "text": "The report was written in just a few days."}, {"id": "a", "text": "The report ignores all industry challenges."}]'::jsonb, 0, '{"strategy": "compiled over months, comprehensive overview = פרטים על תהליך התוצר.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: נכתב במשך חודשים, סקירה מקיפה של אתגרי התעשייה", "סותר את קיום הדוח שהושלם", "הפוך — סותר ''compiled over several months''", "הפוך — סותר ''provides a comprehensive overview of the industry''s challenges''"]}', 0.96, -1.0, 0.25, 2, 'ai', NULL, true),
('692bd827-e970-488d-8d28-2c9c97148d44', 'restatement', 'Since the merger, the two companies have integrated their operations smoothly.', NULL, '[{"id": "d", "text": "The merger between the two companies never took place."}, {"id": "c", "text": "Following the merger, the companies have combined their operations without major problems."}, {"id": "b", "text": "The two companies have struggled to integrate their operations since the merger."}, {"id": "a", "text": "The companies have kept their operations completely separate."}]'::jsonb, 1, '{"strategy": "since merger, integrated smoothly = מאז המיזוג, שולב בחלקה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''since the merger'' — המיזוג כן התרחש", "נכון! אותה משמעות בדיוק: לאחר המיזוג, שילבו פעילות ללא בעיות גדולות", "הפוך — ''struggled'' סותר ''smoothly''", "הפוך — סותר ''integrated their operations smoothly''"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('179d9815-d6f0-4268-a492-e5233feab668', 'restatement', 'The volunteers, working tirelessly through the night, managed to rescue all the trapped animals.', NULL, '[{"id": "a", "text": "The volunteers failed to rescue any of the trapped animals."}, {"id": "c", "text": "The animals were never in any danger."}, {"id": "b", "text": "By working non-stop through the night, the volunteers succeeded in saving every trapped animal."}, {"id": "d", "text": "The volunteers rescued the animals without any effort."}]'::jsonb, 2, '{"strategy": "working tirelessly...managed to rescue all = עבדו ללא לאות...הצליחו להציל את כולם.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''managed to rescue all the trapped animals''", "סותר ''the trapped animals'' — כן היו בסכנה", "נכון! אותה משמעות בדיוק: עבדו כל הלילה, הצליחו להציל את כל בעלי החיים", "הפוך — סותר ''working tirelessly through the night''"]}', 1.0, -1.0, 0.25, 2, 'ai', NULL, true),
('cd6a8752-d99e-48b7-9b5e-7d6859c42edc', 'restatement', 'The professor''s lecture, though brief, covered all the essential points of the topic.', NULL, '[{"id": "b", "text": "The lecture failed to mention any important points."}, {"id": "a", "text": "The professor never gave the lecture."}, {"id": "d", "text": "The lecture was long and covered nothing important."}, {"id": "c", "text": "Despite being short, the lecture addressed every key point of the subject."}]'::jsonb, 3, '{"strategy": "though brief, covered all essential points = למרות קוצר, כיסה את כל הנקודות.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''covered all the essential points''", "סותר את קיום ההרצאה שתוארה", "הפוך — ''long'' סותר ''brief''", "נכון! אותה משמעות בדיוק: קצרה, אך כיסתה את כל הנקודות המרכזיות"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('cea4b0a3-c85f-41d4-8cf0-eb27a7787943', 'restatement', 'The two candidates, despite their differing political views, worked together on the joint project.', NULL, '[{"id": "a", "text": "Even though they held different political opinions, the candidates collaborated on the shared project."}, {"id": "d", "text": "The candidates had identical political views."}, {"id": "b", "text": "The candidates refused to work together because of their differing views."}, {"id": "c", "text": "No joint project ever existed between the candidates."}]'::jsonb, 0, '{"strategy": "despite differing views, worked together = למרות דעות שונות, עבדו יחד.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: דעות פוליטיות שונות, אך שיתפו פעולה בפרויקט המשותף", "הפוך — ''identical'' סותר ''differing''", "הפוך — סותר ''worked together on the joint project''", "סותר את קיום הפרויקט המשותף"]}', 1.06, -1.0, 0.25, 2, 'ai', NULL, true),
('fa87b082-9de7-42d9-8a5e-98fae913c433', 'restatement', 'The airline''s decision to cut costs resulted in a noticeable decline in customer satisfaction.', NULL, '[{"id": "c", "text": "Customer satisfaction remained completely unchanged."}, {"id": "d", "text": "Cutting costs led to customers being noticeably less satisfied with the airline."}, {"id": "b", "text": "The airline never made any decision about costs."}, {"id": "a", "text": "Customer satisfaction improved after the airline cut costs."}]'::jsonb, 1, '{"strategy": "cut costs resulted in decline = קיצוץ הוביל לירידה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''resulted in a noticeable decline''", "נכון! אותה משמעות בדיוק: קיצוץ עלויות הוביל לירידה בשביעות רצון", "סותר ''the airline''s decision to cut costs''", "הפוך — ''improved'' סותר ''decline''"]}', 0.83, -1.0, 0.25, 2, 'ai', NULL, true),
('4ca555ef-7396-4d3e-b8b0-025b8b681ee5', 'restatement', 'The scientist''s findings, though initially met with skepticism, were later validated by independent research.', NULL, '[{"id": "a", "text": "No one ever reacted to the scientist''s findings."}, {"id": "c", "text": "The findings were immediately accepted without any doubt."}, {"id": "b", "text": "Although first regarded with doubt, the findings were subsequently confirmed by other researchers."}, {"id": "d", "text": "The findings were never confirmed by anyone."}]'::jsonb, 2, '{"strategy": "though initially skepticism, later validated = ניגוד תחילה-סוף.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר את קיום התגובות למחקר", "הפוך — סותר ''initially met with skepticism''", "נכון! אותה משמעות בדיוק: תחילה בספק, בסוף אושרו על ידי חוקרים אחרים", "הפוך — סותר ''were later validated by independent research''"]}', 0.79, -1.0, 0.25, 2, 'ai', NULL, true),
('788b568c-bf57-420e-9c64-eb479b1997f2', 'restatement', 'The community rallied together to rebuild the school after the storm destroyed it.', NULL, '[{"id": "c", "text": "The community refused to help rebuild the school."}, {"id": "a", "text": "The school was rebuilt without any community involvement."}, {"id": "d", "text": "The storm caused no damage to the school."}, {"id": "b", "text": "After the storm destroyed the school, the community united to reconstruct it."}]'::jsonb, 3, '{"strategy": "rallied together to rebuild after destroyed = התאחדו לבנות מחדש אחרי הרס.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''rallied together to rebuild''", "הפוך — סותר ''the community rallied together''", "הפוך — סותר ''the storm destroyed it''", "נכון! אותה משמעות בדיוק: אחרי שהסערה הרסה, הקהילה התאחדה לשקם"]}', 0.81, -1.0, 0.25, 2, 'ai', NULL, true),
('9ba82e01-79b1-4ebf-94c3-59c8dbc41a1f', 'reading_comprehension', 'What is the main topic of the passage?', '5c1dde7b-501c-4a9b-9607-e947b9768d08', '[{"id": "c", "text": "The biological functions and benefits of sleep"}, {"id": "d", "text": "The history of sleep research"}, {"id": "a", "text": "Why students should avoid studying at night"}, {"id": "b", "text": "How to treat neurodegenerative diseases"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת תפקידים ביולוגיים ויתרונות של שינה.", "correct_reason": "כל הפסקה עוסקת בתפקידי השינה: ניקוי פסולת, זיכרון, ומערכת חיסון.", "options_analysis": ["נכון! תפקידי ויתרונות השינה = הנושא המרכזי", "לא מוזכר בפסקה כלל", "הפוך — הפסקה ממליצה על שינה טובה, לא מזהירה מפני למידה בלילה", "לא הנושא — מוזכר רק כדוגמה אחת לתפקיד שינה"]}', 1.08, -1.0, 0.25, 2, 'ai', NULL, true),
('0cc98e92-4bbb-465a-aa94-dd95208bac88', 'reading_comprehension', 'According to the passage, what does the glymphatic system do during sleep?', '5c1dde7b-501c-4a9b-9607-e947b9768d08', '[{"id": "b", "text": "It becomes completely inactive"}, {"id": "c", "text": "It helps clear away metabolic waste products from the brain"}, {"id": "a", "text": "It prevents the brain from forming any memories"}, {"id": "d", "text": "It has no known function"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את תפקיד המערכת הגלימפטית בפסקה.", "correct_reason": "הפסקה אומרת: ''becomes significantly more active during sleep and helps clear away metabolic waste products''.", "options_analysis": ["הפוך גמור ממה שנאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה — זו לא הפונקציה המתוארת של המערכת הגלימפטית", "סותר את כל התיאור המפורט של המערכת בפסקה"]}', 0.79, -1.0, 0.25, 2, 'ai', NULL, true),
('d1c263c2-a1b0-41f3-8b97-62d38233e65d', 'reading_comprehension', 'The word "consolidation" in the passage most closely means:', '5c1dde7b-501c-4a9b-9607-e947b9768d08', '[{"id": "b", "text": "confusion"}, {"id": "c", "text": "destruction"}, {"id": "a", "text": "the process of strengthening or making something more solid"}, {"id": "d", "text": "forgetting"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''memory consolidation, the process by which...memories...are strengthened''.", "correct_reason": "consolidation = ביסוס/חיזוק.", "options_analysis": ["לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! consolidation = ביסוס/חיזוק, כפי שמוסבר במפורש בפסקה", "הפוך גמור למשמעות המילה"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
('9de47548-ed89-40cc-8d64-55cd49675c84', 'reading_comprehension', 'According to the passage, what happens to students who sleep well after studying?', '5c1dde7b-501c-4a9b-9607-e947b9768d08', '[{"id": "d", "text": "They forget everything they studied"}, {"id": "b", "text": "They perform worse on tests than students who don''t sleep"}, {"id": "a", "text": "They lose the ability to concentrate the next day"}, {"id": "c", "text": "They tend to retain information better than those who stay up late cramming"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הדוגמה על סטודנטים בפסקה.", "correct_reason": "הפסקה אומרת: ''Students who sleep well after studying...tend to retain information better than those who stay up late cramming''.", "options_analysis": ["הפוך גמור ממה שנאמר בפסקה", "הפוך — הפסקה אומרת שהם דווקא שומרים מידע טוב יותר", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה"]}', 0.77, -1.0, 0.25, 2, 'ai', NULL, true),
('1dc7cba8-e2e4-4be7-8148-03e9d2c5d676', 'reading_comprehension', 'What warning do sleep researchers give, according to the passage?', '5c1dde7b-501c-4a9b-9607-e947b9768d08', '[{"id": "a", "text": "That viewing sleep as a sacrificeable luxury carries significant long-term health risks"}, {"id": "d", "text": "That people should never work more than a few hours a day"}, {"id": "b", "text": "That sleep is only important for students"}, {"id": "c", "text": "That sleep has no real health benefits"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את האזהרה בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''a habit that sleep researchers warn carries significant long-term health risks''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "סותר את הפסקה שמתארת יתרונות רחבים של שינה לכולם", "הפוך גמור מכל תוכן הפסקה"]}', 0.8, -1.0, 0.25, 2, 'ai', NULL, true);